// Baustein « Speichern » – Prüfung der Bestätigungsanfrage.
// Gespeichert wird nur der Text eines bestehenden ENTWURFS (von « Verfassen » erstellt): Der bestätigte Text ist der, den
// die Pflegekraft gelesen und gegebenenfalls korrigiert hat, zugeordnet zu diesem Entwurf.
const e = $input.first().json ?? {};
const id = String(e.brouillon_id ?? '');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) throw new Error('Ungültige brouillon_id');
const texte = String(e.texte ?? '').trim();
if (!texte || texte.length > 20000) throw new Error('Text leer oder zu lang (höchstens 20 000 Zeichen)');
return [{ json: { brouillon_id: id, texte, valide_par: String(e.valide_par ?? 'Pflegekraft (nicht identifiziert)').slice(0, 80), soignant_id: String(e.soignant_id ?? '').slice(0, 40) } }];

// Baustein « Speichern » – Ergebnis der Bestätigung und zugehöriges Prüfereignis.
const c = $('Bestätigung prüfen').first().json;
const v = $('Entwurf bestätigen').first().json;

const resultat = v.validation_id
  ? {
      ok: true,
      validation_id: v.validation_id,
      brouillon_id: c.brouillon_id,
      patient_id: v.patient_id,
      mode: v.mode,
      action: v.action,
      modifiee: v.modifiee,
      texte: c.texte,
      valide_par: c.valide_par,
      soignant_id: c.soignant_id,
    }
  : { ok: false, erreur: 'Entwurf nicht gefunden oder bereits bestätigt.', brouillon_id: c.brouillon_id };

return [
  {
    json: {
      ...resultat,
      evenement_journal: {
        evenement: resultat.ok ? 'validation' : 'validation_refusee',
        patient_id: resultat.patient_id ?? null,
        mode: resultat.mode ?? null,
        action: resultat.action ?? null,
        details: { brouillon_id: c.brouillon_id, modifiee: resultat.modifiee ?? null, valide_par: c.valide_par, soignant_id: c.soignant_id || null },
      },
    },
  },
];

// Baustein « Speichern » – Ausgang: das Ergebnis der Bestätigung (ohne das Protokollereignis).
const { evenement_journal, ...resultat } = $('Ergebnis der Bestätigung').first().json;
return [{ json: resultat }];
